use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-joint-ring-census176";const OLD:&str="/home/ubuntu/src/zopro-perf-work/g2-joint-ring-screen176";
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!Path::new(&format!("{R}/plan.json")).exists());let mut pins:BTreeMap<String,String>=serde_json::from_slice(&fs::read(format!("{OLD}/pins.json")).unwrap()).unwrap();for(p,h)in &pins{assert_eq!(&hash(p),h);}for n in["analysis.json","review.json","study.rs","split.rs","inputs.json"]{let p=format!("{OLD}/{n}");pins.insert(p.clone(),hash(&p));}for n in["setup.rs","setup","census.rs","design.md"]{let p=format!("{R}/{n}");pins.insert(p.clone(),hash(&p));}
let compiler="/home/ubuntu/.rustup/toolchains/1.98.1-x86_64-unknown-linux-gnu/bin/rustc";let d="/home/ubuntu/src/zopro-perf-work/tool-target/release/deps";let field="/home/ubuntu/src/zopro-perf-work/g2-vector-sign-default175/frozen/candidate/libzopro_bn254-1200e63547baa41c299a48e3221f1cef85990b0369f17452dc12eb17045f9713.rlib";
let compile=|test:bool|{let mut v=vec![compiler.to_string(),"--edition=2021".into(),"-O".into(),"-C".into(),"target-cpu=native".into(),format!("{R}/census.rs"),"-L".into(),format!("dependency={d}"),"-L".into(),format!("dependency={}",Path::new(field).parent().unwrap().display()),"--extern".into(),format!("serde_json={d}/libserde_json-cdebb9338c2784ad.rlib"),"--extern".into(),format!("zopro_bn254={field}")];if test{v.push("--test".into());}v.extend(["-o".into(),format!("{R}/{}",if test{"census-tests"}else{"census"})]);v};
// The included parent recoder's three tests remain compiled, but only the
// three NEW tests are selected explicitly; do not rerun inherited tests.
let step=|n:&str,argv:Vec<String>,required:Vec<&str>|json!({"kind":"command","name":n,"argv":argv,"environment":{},"unfiltered":false,"required_tests":required,"timeout_seconds":300});
let mut steps=vec![step("compile-new-tests",compile(true),vec![])];for name in["queue_spills_preserve_complete_addition_accounting","actual_weighted_tree_topology_full_and_empty","indexed_tile_and_group_boundaries"]{let full=format!("tests::{name}");steps.push(step(name,vec![format!("{R}/census-tests"),"--exact".into(),full,"--test-threads=1".into()],vec![]));}steps.push(step("compile-census",compile(false),vec![]));steps.push(step("actual-stream-tree-census",vec![format!("{R}/census")],vec![]));
fs::write(format!("{R}/pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(format!("{R}/plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"source_pins":format!("{R}/pins.json"),"steps":steps})).unwrap()).unwrap();println!("Prepared six-step census with three new tests only, {} pins",pins.len());}
